"""Finite pure-document checker for this business-carrier proposal only.
Imports: base64/copy/hashlib/json/pathlib/re, all stdlib. Read only own new docs,
old57 fixed pure-doc bytes and newly authorized D1 pure-doc snapshots. No writes,
no product/model import, no schema engine, no subprocess, no actual/runtime claim.
"""
import base64
import copy
import hashlib
import json
import pathlib
import re

W = pathlib.Path.cwd()
O = W / 'docs/iterations/I05/d2-business-carrier-design'
R = W / 'docs/reviews/I05/d2-business-carrier-design'

def pairs(items):
    out = {}
    for k, v in items:
        if k in out:
            raise ValueError('duplicate key')
        out[k] = v
    return out

def invalid(v):
    raise ValueError('nonfinite')

def read(p):
    b = p.read_bytes()
    assert not b.startswith(b'\xef\xbb\xbf')
    return json.loads(b.decode(), object_pairs_hook=pairs, parse_constant=invalid)

def exact(a,b):
    if type(a) is not type(b):
        return False
    if type(a) is dict:
        return a.keys()==b.keys() and all(exact(a[k],b[k]) for k in a)
    if type(a) is list:
        return len(a)==len(b) and all(exact(x,y) for x,y in zip(a,b))
    return a==b

def c(value):
    def only(v):
        assert type(v) in (dict,list,str,int,bool,type(None))
        if type(v) is dict:
            assert all(type(k) is str for k in v)
            for item in v.values(): only(item)
        elif type(v) is list:
            for item in v: only(item)
        elif type(v) is str:
            v.encode('utf8')
    only(value)
    return json.dumps(value,ensure_ascii=False,sort_keys=True,separators=(',',':'),allow_nan=False).encode()

def blob(v):
    b=base64.b64decode(v['base64'],validate=True)
    assert base64.b64encode(b).decode()==v['base64']
    assert len(b)==v['bytes'] and hashlib.sha256(b).hexdigest()==v['sha256']
    return b

G=read(O/'wire-grammar.json')
D=G['definitions']

def shape(value,t):
    # Finite DSL syntax only. Does NOT authenticate pins, implement relationships,
    # validate external header schema, or execute any original model function.
    if 'ref' in t:
        node=D[t['ref']]
        if node['kind']=='record':
            return (type(value) is dict and set(value)==set(node['required'])==set(node['fields'])
                    and all(shape(value[k],v['type']) for k,v in node['fields'].items()))
        if node['kind']=='union':
            return sum(shape(value,v) for v in node['variants'])==1
        if node['kind']=='external-strict':
            return False  # adopted full external v3 header pin unavailable here
        if type(value) is not {'string':str,'integer':int,'boolean':bool,'null':type(None)}[node['type']]:
            return False
        if type(value) is str:
            try:value.encode('utf8')
            except UnicodeError:return False
            if 'pattern' in node and re.fullmatch(node['pattern'],value) is None:return False
            if 'maxLength' in node and len(value)>node['maxLength']:return False
        if type(value) is int and value<node.get('minimum',value):return False
        return True
    if 'nullable' in t:return value is None or shape(value,t['nullable'])
    if 'array' in t:return type(value) is list and all(shape(x,t['array']) for x in value)
    if 'enum' in t:return any(exact(value,x) for x in t['enum'])
    if 'const' in t:return exact(value,t['const'])
    if t.get('type')=='integer':return type(value) is int
    raise AssertionError(t)

def refs(t):
    if type(t) is dict:
        if 'ref' in t and type(t['ref']) is str:yield t['ref']
        for v in t.values():yield from refs(v)
    elif type(t) is list:
        for v in t:yield from refs(v)

def guard(name,v):
    if name=='negotiation':
        if not v['approved']:return 'not-started'
        return 'eligible-design-only' if (v['consumer'],v['profile'],v['header'],v['stream'])==('3.0.0',4,2,2) else 'reject'
    if name=='metadata':
        if not v['requestedCompatible']:return 'pending'
        return 'eligible-design-only' if all(v[k] for k in ['codec','layout','recipe','bytesVerified','liveWitness','sameIssue']) else 'reject'
    if name=='domain':
        if v['graph']!=v['consumerOwner']:return 'reject'
        return 'eligible-design-only' if v['witness'] else 'pending'
    if name=='digests':
        if v['oldRaw']!=v['savedOldRaw']:return 'reject'
        return 'eligible-design-only' if v['oldRecipeKnown'] else 'pending'
    if name=='stage-flow':
        return 'reject' if v['earlierCaseRejected'] and v['sameCaseLaterCall'] else 'eligible-design-only'
    if name=='first-error':
        if v['first']!=v['reported']:return 'reject'
        return 'preserved-A1-pending' if not v['reachedA1'] else 'eligible-design-only'
    if name=='collection':
        if type(v['count']) is not int or type(v['full']) is not bool:return 'reject'
        good=(v['selector']=='full-v1' and v['count']==417 and v['full']) or (v['selector'] in ['b1-semantic-1x-v1','b1-semantic-10x-v1'] and v['count']==1 and not v['full'])
        return 'eligible-design-only' if good else 'reject'
    raise AssertionError(name)

I=read(R/'input-identity.json')
for item in I['oldD2ImmutableInventory']:
    b=(W/item['path']).read_bytes()
    assert len(b)==item['bytes'] and hashlib.sha256(b).hexdigest()==item['sha256']
assert len(I['oldD2ImmutableInventory'])==57
for item in I['newD1AuthorizedPureInputs']:
    b=(R/item['local']).read_bytes()
    assert len(b)==item['bytes'] and hashlib.sha256(b).hexdigest()==item['sha256']
for item in I['rootInputs']:
    b=(R/item['local']).read_bytes()
    assert len(b)==item['bytes'] and hashlib.sha256(b).hexdigest()==item['sha256']
F=read(O/'field-map.json')
E=read(O/'acceptance-rejects.json')
X=read(O/'forward-delta.json')
M=read(O/'missing-materials.json')
keys={(n,k) for n,node in D.items() for k in node.get('fields',{})}
assert len(keys)==F['fieldCount']==251
assert {(x['definition'],x['field']) for x in F['fields']}==keys
for row in F['fields']:
    spec=D[row['definition']]['fields'][row['field']]
    assert exact(row['type'],spec['type']) and row['required'] is True
    assert row['grammarPointer']=='/definitions/'+row['definition']+'/fields/'+row['field']
    assert row['meaning']==spec['meaning'] and row['owner']==spec['owner']
for node in D.values():
    expressions=[v['type'] for v in node.get('fields',{}).values()]+node.get('variants',[])
    for expression in expressions:
        for name in refs(expression):assert name in D,name
    for field in node.get('fields',{}).values():
        for rule in field['rule'].split('/'):assert rule in G['relationshipRules'],rule
assert len(G['definitions']['PinnedHeader']['rootKeys'])==18
H=read(W/'docs/reviews/I05/d2-consumer-design/fixed-inputs/06-runtime-header.schema.json')
assert G['definitions']['PinnedHeader']['rootKeys']==list(H['properties'])
idx=read(R/'fixed-d1/forward-schema-change-index.json')
assert exact(G['definitions']['PinnedHeader']['proposedLiteralTransform'],[x for x in idx['schemaLiteralChanges'] if x['schema']=='runtime-header.schema.json'])
assert D['PinnedHeader']['actualAcceptedPin'] is None
assert len(F['legacyMandatoryMaterialDestinations'])==15 and len(F['fullLegacyFamilies'])==13
assert all(x['newConcreteDestination'] for x in F['legacyMandatoryMaterialDestinations'])
assert len(M['requests'])==8 and all(x['actualPin'] is None for x in M['requests'])
plan=read(R/'fixed-d1/dependency-plan.json');matrix=read(R/'fixed-d1/guard-scope-matrix.json')
assert exact(X['exactProposedUnionPackageVersions'],plan['proposedUnionPackageVersions']) and len(X['exactProposedUnionPackageVersions'])==26
assert exact(X['sixDirectRequirements'],plan['preferredParentUnionDirectRequirements']) and len(X['sixDirectRequirements'])==6
assert exact(X['distinctSets'],matrix['counts'])
assert len(X['nineConflicts'])==9 and len(X['twentyOneOldOnly'])==21
for row in X['nineConflicts']+X['twentyOneOldOnly']:
    ix=int(row['sourcePointer'].split('/')[-1]);assert exact(row['row'],matrix['rows'][ix])
    assert row['row']['parentDefaultScope']['actualApprovedPin'] is None
assert all(x is None for x in X['futureApprovedPins'].values())
missing=extra=wrong=0
for name,value in E['recordShapeSamples'].items():
    assert D[name]['kind']=='record' and shape(value,{'ref':name}),name
    for key in D[name]['required']:
        altered=copy.deepcopy(value);del altered[key]
        assert not shape(altered,{'ref':name}),(name,key,'missing');missing+=1
        typ=D[name]['fields'][key]['type']
        invalid_value=next(v for v in [None,True,0,1,'',{},[]] if not shape(v,typ))
        altered=copy.deepcopy(value);altered[key]=invalid_value
        assert not shape(altered,{'ref':name}),(name,key,'wrong-type');wrong+=1
    altered=copy.deepcopy(value);altered['unexpected-field']=None
    assert not shape(altered,{'ref':name}),name;extra+=1
for sample in E['completeCarrierSamples']:
    assert shape(sample['value'],{'ref':'Carrier'}),sample['name']
    v=sample['value']
    if v['observationState']=='not-started':
        assert v['runId'] is v['stdout'] is v['stderr'] is v['actualExitCode'] is v['signal'] is None
        assert not v['frames'] and not v['artifacts'] and not v['collectionComplete']
    else:
        assert v['header']['state']=='malformed' and v['header']['payload'] is None
        assert v['signal'] is not None and v['actualExitCode'] is None
        for raw in sample['rawFixtures']:
            b=blob(raw['bytes']);assert len(b)==raw['file']['bytes'] and hashlib.sha256(b).hexdigest()==raw['file']['sha256']
for vector in E['hashVectors']:
    canonical=c(vector['value']);assert canonical==blob(vector['canonicalUtf8'])
    pre=b'ontolearn/i05/'+vector['tag'].encode()+b'\0'+canonical
    assert pre==blob(vector['domainSeparatedPreimage']) and hashlib.sha256(pre).hexdigest()==vector['digest']
    assert hashlib.sha256(canonical).hexdigest()!=vector['digest']
vec=E['terminalPrefixVector'];prefix=blob(vec['rawPrefix']);terminal=blob(vec['terminal'])
assert blob(vec['wholeRaw'])==prefix+terminal
assert vec['priorPrefixBytes']==len(prefix) and vec['priorPrefixSha256']==hashlib.sha256(prefix).hexdigest()
assert vec['priorPrefixSha256']!=hashlib.sha256(prefix+terminal).hexdigest()
assert all(guard(x['predicate'],x['value'])==x['expected'] for x in E['finiteGuardCases'])
assert len(E['negativeDesigns'])==65
for name in ['spec.md','handoff.md']:
    text=(O/name).read_text();assert 'function.**code**' not in text and 'function.__code__' in text
assert X['target']['actualFullV3ProtocolPin'] is None and X['target']['actualBusinessAdoptionPin'] is None
assert 'runtimeValidationReceipt' not in D['Carrier']['fields'] and 'validation' not in D['BusinessValidationBinding']['fields']
print(json.dumps({'evidenceClass':'finite-new-design-structure-and-detached-examples-only','old57Immutable':True,'D1FixedPlanInputs':5,'definitions':len(D),'fields':len(keys),'requiredMissingNegatives':missing,'extraObjectNegatives':extra,'wrongTypeNegatives':wrong,'completeSyntheticCarriers':2,'hashVectors':len(E['hashVectors']),'finiteGuardCases':len(E['finiteGuardCases']),'normativeNegativeDesigns':65,'legacyMaterials':15,'families':13,'newHeaderRootKeys':18,'unionPackages':26,'ownerConflictPinsStillNull':30,'schemaEngineValidation':False,'productExecuted':False,'modelFunctionsExecuted':False,'independentReview':'pending'},ensure_ascii=False,indent=2))
